package com.hms.onboarding;
import com.hms.availability.*; import com.hms.doctors.*; import com.hms.social.*; import com.hms.tenancy.*; import com.hms.website.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/setup-health") public class SetupHealthController {private final TenantRepository tenants;private final DoctorRepository doctors;private final DoctorAvailabilityRepository availability;private final WebsiteSettingsRepository website;private final SocialConnectionRepository social;public SetupHealthController(TenantRepository t,DoctorRepository d,DoctorAvailabilityRepository a,WebsiteSettingsRepository w,SocialConnectionRepository s){tenants=t;doctors=d;availability=a;website=w;social=s;} @GetMapping public SetupHealthDto get(@PathVariable String tenantSlug){Tenant tenant=tenants.findBySlug(tenantSlug).orElseThrow(()->new TenantNotFoundException(tenantSlug));List<Doctor> doctorRows=doctors.findAllByTenantIdOrderByDisplayName(tenant.getId());boolean schedules=doctorRows.stream().anyMatch(d->!availability.findAllByTenantIdAndDoctorIdOrderByDayOfWeekAscStartTimeAsc(tenant.getId(),d.getId()).isEmpty());WebsiteSettings settings=website.findByTenantId(tenant.getId()).orElse(null);List<SetupHealthItem> checks=List.of(new SetupHealthItem("DOCTORS","At least one active doctor",doctorRows.stream().anyMatch(Doctor::isActive)),new SetupHealthItem("SCHEDULES","At least one doctor schedule",schedules),new SetupHealthItem("PHONE","Hospital phone number",tenant.getPrimaryPhone()!=null&&!tenant.getPrimaryPhone().isBlank()),new SetupHealthItem("LOGO","Hospital logo",settings!=null&&settings.getLogoUrl()!=null&&!settings.getLogoUrl().isBlank()),new SetupHealthItem("SOCIAL","At least one social connection",!social.findAllByTenantIdOrderByPlatformAsc(tenant.getId()).isEmpty()),new SetupHealthItem("WEBSITE","Website published",settings!=null&&settings.isPublished()));return new SetupHealthDto((int)checks.stream().filter(SetupHealthItem::complete).count(),checks.size(),checks);}}
